export const useUpdateTool = (onSuccess?: () => void) => {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: ({ id, data }: { id: number; data: Partial<Tool> }) => toolMutations.update(id, data),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['tools'] }); onSuccess?.() },
  })
}

{mode === 'delete' && tool && (
  <div className="flex flex-col gap-4">
